<script setup lang="ts">
import {computed,nextTick,ref,watch} from 'vue';
import MDatePicker from '../MDatePicker.vue';import MTimePicker from './MTimePicker.vue';import MValueBridge from './MValueBridge.vue';
import {parseISODate} from '../calendarDate';import {formatTime,timeSeconds,timeError,useDraftReset} from './shared';import {useReferenceConfig} from './locale';import type {MDateTimePickerProps} from './types';
const props=withDefaults(defineProps<MDateTimePickerProps>(),{step:60,showSeconds:false});const emit=defineEmits<{ 'update:modelValue':[value:string] }>();const {t}=useReferenceConfig();const root=ref<HTMLElement>(),date=ref(props.modelValue.split('T')[0]||''),time=ref(props.modelValue.split('T')[1]||'');
function canonical(value:string){const parts=value.split('T'),seconds=timeSeconds(parts[1]||'');return parseISODate(parts[0]||'')&&seconds!==null?`${parts[0]}T${formatTime(seconds,true)}`:null;}
const error=computed(()=>{const min=props.min?canonical(props.min):null,max=props.max?canonical(props.max):null;if(props.min&&!min||props.max&&!max||min&&max&&min>max)return t('date.timeConfig','日期时间边界无效。');if(!date.value&&!time.value)return '';const value=canonical(`${date.value}T${time.value}`);if(!value)return t('date.timeIncomplete','请填写完整有效的日期与时间。');if(min&&value<min||max&&value>max)return t('date.timeBounds','日期时间超出可用范围。');return timeError(time.value,props.min?.split('T')[0]===date.value?props.min.split('T')[1]:undefined,props.max?.split('T')[0]===date.value?props.max.split('T')[1]:undefined,props.step,t);});
function restore(){[date.value,time.value]=[props.modelValue.split('T')[0]||'',props.modelValue.split('T')[1]||''];}
function change(which:'date'|'time',value:string){if(props.disabled||props.readonly)return;if(which==='date')date.value=value;else time.value=value;if(!value){emit('update:modelValue','');void nextTick(restore);}else if(!error.value){emit('update:modelValue',`${date.value}T${time.value}`);void nextTick(restore);}}
watch(()=>props.modelValue,restore);useDraftReset(root,restore);
</script>
<template><div ref="root" class="ui-ri" role="group" :aria-label="label"><span class="ui-ri__label">{{label}}</span><div class="ui-ri__grid"><MDatePicker :model-value="date" :label="t('date.date','日期')" :form="form" :required="required" :min="min?.split('T')[0]" :max="max?.split('T')[0]" :disabled="disabled" :readonly="readonly" @update:model-value="change('date',$event)"/><MTimePicker :model-value="time" :label="t('date.time','时间')" :form="form" :required="required" :min="min?.split('T')[0]===date?min.split('T')[1]:undefined" :max="max?.split('T')[0]===date?max.split('T')[1]:undefined" :step="step" :show-seconds="showSeconds" :disabled="disabled" :readonly="readonly" @update:model-value="change('time',$event)"/></div><p v-if="error" class="ui-ri__error">{{error}}</p><MValueBridge v-bind="props" :values="modelValue?[modelValue]:[]" :error="error"/></div></template>
